function total_chars(lst: seq<string>): int
    reads lst
    ensures result >= 0
{
    var count := 0;
    var i := 0;
    while i < |lst|
        invariant 0 <= i <= |lst|
        invariant count == sum_length(lst, i)
    {
        count := count + |lst[i]|;
        i := i + 1;
    }
    return count;
}

function sum_length(lst: seq<string>, n: int): int
    reads lst
    requires 0 <= n <= |lst|
    ensures result == (if n == 0 then 0 else sum_length(lst, n - 1) + |lst[n - 1]|)
{
    if n == 0 {
        return 0;
    } else {
        return sum_length(lst, n - 1) + |lst[n - 1]|;
    }
}

